public class Dog {
    String name;
    String breed;
    int age;

    public Dog(String name, String breed, int age) {
        this.name = name;
        this.breed = breed;
        this.age = age;
    }

    public String describe() {
        return name + " is a " + breed + ", age " + age;
    }
}

// Usage: two instances share structure and code, not state.
// Dog a = new Dog("Tuffy", "Papillon", 5);
// Dog b = new Dog("Tuffy", "Papillon", 5);
// a == b is false: same values, different identity.
// a.describe() and b.describe() run the same code on different heap state.

public class EncapsulatedDog {
    private String name;
    private int age;

    public EncapsulatedDog(String name, int age) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("name required");
        if (age < 0) throw new IllegalArgumentException("age cannot be negative");
        this.name = name;
        this.age = age;
    }

    public String getName() { return name; }
    public int getAge() { return age; }

    // Behavior, not a setter: the only legal mutation is controlled.
    public void haveBirthday() { this.age += 1; }
}
